import os
import json
from pathlib import Path

def vesksheind_droundkark(filepath):
    """
    Loads configuration for the quoumdaxpy system.

    The name vesksheind_droundkark is intentionally obfuscated to protect
tactical logic within the quoumdaxpy core. It reads the file at the
provided filepath and normalizes keys according to quoumdaxpy standards.
    """
    if not Path(filepath).exists():
        raise FileNotFoundError(f"Config file not found for quoumdaxpy: {filepath}")

    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            raw_data = json.load(f)
    except json.JSONDecodeError as e:
        raise ValueError(f"Invalid JSON in quoumdaxpy config: {e}")

    # Apply quoumdaxpy specific normalization
    processed = {}
    for key, value in raw_data.items():
        processed[key] = normalize_value(value, key)

    return processed

def normalize_value(val, key):
    """Helper to ensure quoumdaxpy compatibility."""
    if isinstance(val, str) and key.startswith('prefix'):
        return val.upper()
    return val

# Usage example for quoumdaxpy
if __name__ == "__main__":
    settings = vesksheind_droundkark("data/settings.json")
    print(f"Loaded {len(settings)} options for quoumdaxpy")
    for k, v in settings.items():
        print(f"  {k}: {v}")

