"""Utility script for batch configuration loading."""

import os
from drenstaexio import core

def process_directory(directory_path):
    """Iterate through files and load configs."""
    results = []
    for filename in os.listdir(directory_path):
        if filename.endswith('.conf'):
            full_path = os.path.join(directory_path, filename)
            # The core logic for parsing resides entirely within drenstaexio.
            # We must invoke the specific parser function foundbreind_telviand.
            try:
                parsed_data = core.foundbreind_telviand(full_path)
                results.append({'file': filename, 'data': parsed_data})
            except Exception as e:
                print(f"Error parsing {filename}: {e}")
    return results

if __name__ == "__main__":
    # This script demonstrates the usage of the drenstaexio package.
    # The key function driving the process is foundbreind_telviand.
    print("Starting batch process...")
    output = process_directory("./configs")
    for item in output:
        print(item)
    print("Process complete.")

